// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadOswald = makeLoadFont('Oswald');
import { makeStar } from "@remotion/shapes";

const { fontFamily: oswaldFamily } = loadOswald();



export type MedalsSequenceProps = Record<string, any>;

// Shared component for individual medals to encapsulate their own animation offsets
const MedalItem: React.FC<{
  data: MedalsSequenceProps["medals"][0];
  index: number;
  scaleFactor: number;
  frame: number;
  fps: number;
  height: number;
}> = ({ data, index, scaleFactor: s, frame, fps, height }) => {
  const { label, labelColor, medalMainColor, medalInnerColor, medalStarColor, ribbonColor } = data;

  // Stagger entrances by 20 frames each
  const delay = index * 20;
  
  // Spring handles the "pop up" dynamics (overshoot & settle)
  const entryProgress = spring({
    frame: frame - delay,
    fps,
    config: { damping: 12, stiffness: 90, mass: 1.2 },
  });

  // Calculate visual properties from progress
  const scale = entryProgress;
  const yOffset = interpolate(entryProgress, [0, 1], [300 * s, 0], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });
  
  const opacity = interpolate(entryProgress, [0, 0.4], [0, 1], { 
    extrapolateLeft: "clamp", 
    extrapolateRight: "clamp" 
  });

  // Subtle continuous floating motion post-entrance
  const floatOffset = Math.sin(Math.max(0, frame - delay) / 30) * 8 * s * entryProgress;
  const totalY = yOffset + floatOffset;

  // Generate crisp star path once
  // outerRadius: 42 creates an 84x84 bounding box centered at (42, 42)
  const star = useMemo(() => makeStar({ innerRadius: 18, outerRadius: 42, points: 5 }), []);

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        width: 300 * s,
        opacity,
        transform: `translateY(${totalY}px) scale(${scale})`,
        transition: "none", // Force pure frame-driven rendering
      }}
    >
      {/* SVG bounds are styled dynamically, but internal coords use fixed viewbox for perfect scaling */}
      <svg width={240 * s} height={384 * s} viewBox="0 0 200 320" style={{ overflow: "visible", transition: "none" }}>
        <defs>
          <filter id={`shadow-${index}`} x="-30%" y="-30%" width="160%" height="160%">
            <feDropShadow dx="0" dy="8" stdDeviation="6" floodOpacity="0.4" floodColor="#000" />
          </filter>
        </defs>

        <g>
          {/* Ribbons */}
          {/* Right leg */}
          <polygon points="190,-10 145,-10 105,150 150,150" fill={ribbonColor} style={{ transition: "none" }} />
          {/* Shadow representing tuck/fold overlap */}
          <polygon points="105,150 150,150 120,100 95,120" fill="rgba(0,0,0,0.2)" style={{ transition: "none" }} />
          {/* Left leg */}
          <polygon points="10,-10 55,-10 95,150 50,150" fill={ribbonColor} style={{ transition: "none" }} />
        </g>

        {/* Medal Body (Filtered as one unit) */}
        <g transform="translate(0, 110)" filter={`url(#shadow-${index})`} style={{ transition: "none" }}>
          {/* Attachment loop */}
          <circle cx="100" cy="15" r="14" fill="none" stroke={medalMainColor} strokeWidth="10" style={{ transition: "none" }} />
          <rect x="90" y="15" width="20" height="18" fill={medalMainColor} style={{ transition: "none" }} />

          {/* Outer edge */}
          <circle cx="100" cy="90" r="75" fill={medalMainColor} style={{ transition: "none" }} />
          
          {/* Inner bed */}
          <circle cx="100" cy="90" r="62" fill={medalInnerColor} style={{ transition: "none" }} />

          {/* Decorative dotted laurel/ring substitute */}
          <circle 
            cx="100" 
            cy="90" 
            r="54" 
            fill="none" 
            stroke={medalMainColor} 
            strokeWidth="3" 
            strokeDasharray="6 4" 
            style={{ transition: "none" }} 
          />

          {/* Star (translated so its center (42,42) sits exactly at local (100,90)) */}
          <path d={star.path} fill={medalStarColor} transform="translate(58, 48)" style={{ transition: "none" }} />
        </g>
      </svg>

      <div
        style={{
          marginTop: 15 * s,
          fontSize: 75 * s,
          fontWeight: 700,
          color: labelColor,
          textShadow: `0px ${4 * s}px ${10 * s}px rgba(0,0,0,0.6)`,
          textTransform: "capitalize",
          transition: "none",
        }}
      >
        {label}
      </div>
    </div>
  );
};

const MedalsSequence: React.FC<MedalsSequenceProps> = ({
  backgroundColor = "#04153a",
  transparentBackground = false,
  durationInSeconds = 6,
  medals = [
    { label: "Good", labelColor: "#e08f58", medalMainColor: "#c57e54", medalInnerColor: "#a8613a", medalStarColor: "#e29d74", ribbonColor: "#b56834" },
    { label: "Better", labelColor: "#d0d5dc", medalMainColor: "#d0d5dc", medalInnerColor: "#a5aebc", medalStarColor: "#f0f3f6", ribbonColor: "#297cc0" },
    { label: "Best", labelColor: "#f3af22", medalMainColor: "#eeb623", medalInnerColor: "#c99312", medalStarColor: "#ffda45", ribbonColor: "#fab518" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  
  // Master scale factor relative to 1080p target
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: oswaldFamily,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "row",
          gap: 30 * s,
          justifyContent: "center",
          alignItems: "flex-end", // Align from bottom so different states hold their ground
          transition: "none",
        }}
      >
        {medals.map((medalData, index) => (
          <MedalItem
            key={`${medalData.label}-${index}`}
            data={medalData}
            index={index}
            scaleFactor={s}
            frame={frame}
            fps={fps}
            height={height}
          />
        ))}
      </div>
    </AbsoluteFill>
  );
};

export default MedalsSequence;